<script setup lang="ts">
import{computed,onUnmounted,ref}from'vue'
import{subjectFor,type Bot,type Account}from'./model'
import{sealCredentialInput}from'./credential-input'
interface Job{ref:string;state:string;sequence:number;role_states:Record<string,string>;account?:Account}
const props=defineProps<{bots:Bot[];busy:boolean;invoke:<T>(action:string,payload?:Record<string,unknown>)=>Promise<T>}>()
const emit=defineEmits<{changed:[];working:[boolean]}>()
const botIndex=ref(0),actor=ref(''),value=ref(''),job=ref<Job|null>(null),working=ref(false),error=ref(''),notice=ref(''),stopping=ref(false)
const bot=computed(()=>props.bots[botIndex.value]);let disposed=false
async function run(resume=false){if(working.value||props.busy)return;working.value=true;stopping.value=false;emit('working',true);error.value='';notice.value='';try{if(!resume){if(!bot.value||!actor.value.trim())throw Error('请选择机器人并填写本人聊天用户ID。');const {public_key}=await props.invoke<{public_key:JsonWebKey}>('vault.public_key');const box=await sealCredentialInput(value.value.trim(),public_key,'account.overseas.import');value.value='';job.value=(await props.invoke<{import:Job}>('accounts.overseas.start',{subject:subjectFor(bot.value,actor.value),box})).import}while(job.value?.state==='discovering'&&!disposed&&!stopping.value){job.value=(await props.invoke<{import:Job}>('accounts.overseas.step',{ref:job.value.ref,sequence:job.value.sequence})).import}if(job.value?.state==='bound'){notice.value='HoYoLab账号已加密保存，各游戏可共用此授权。';emit('changed')}else if(stopping.value||disposed){await props.invoke('accounts.overseas.cancel',{ref:job.value?.ref}).catch(()=>{});job.value=null;notice.value='海外授权流程已停止。'}}catch(e){error.value=e instanceof Error?e.message:'海外授权未完成，可重试当前步骤。'}finally{value.value='';working.value=false;emit('working',false)}}
async function cancel(){stopping.value=true;if(working.value)return;if(job.value){await props.invoke('accounts.overseas.cancel',{ref:job.value.ref}).catch(()=>{});job.value=null}}
onUnmounted(()=>{disposed=true;value.value='';void cancel()})
</script>
<template><details class="overseas-authorization"><summary>海外 HoYoLab 账号授权</summary><div><p>国服使用上方米游社扫码。海外在这里加密导入本人的 HoYoLab Cookie，一次授权供三个游戏共用；原文不会进入游戏插件或聊天。需要账号ID与LToken，或SToken v2与MID以换取凭据。完整抽卡等业务还需要CookieToken v2和MID。</p><form @submit.prevent="run()"><fieldset :disabled="busy||working"><legend>绑定到本人聊天身份</legend><label>机器人<select v-model="botIndex"><option v-for="(b,i) in bots" :key="b.source_adapter+':'+b.id" :value="i">{{b.name||b.id}} · {{b.source_protocol}} / {{b.source_adapter}}</option></select></label><label>聊天用户ID<input v-model="actor" maxlength="256" required></label><label>本人 HoYoLab Cookie<input v-model="value" type="password" autocomplete="off" maxlength="8192" required></label><button :disabled="!bot||!actor.trim()||!value.trim()||job?.state==='discovering'">加密导入海外授权</button></fieldset></form><p v-if="error" role="alert" class="danger-text">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="job">{{job.state==='bound'?'已保存':'角色发现进度'}} · {{Object.keys(job.role_states).length}} / 3</p><div v-if="job?.state==='discovering'" class="actions"><button v-if="!working" :disabled="busy" @click="run(true)">重试当前步骤</button><button :disabled="stopping" @click="cancel">停止海外授权流程</button></div></div></details></template>
<style scoped>.overseas-authorization{margin-block:20px;border:1px solid var(--raylea-color-border);padding:18px;border-radius:12px}.overseas-authorization summary{font-weight:600;cursor:pointer}.overseas-authorization>div,.overseas-authorization fieldset{display:grid;gap:14px;min-width:0;margin-top:14px}.overseas-authorization label{display:grid;gap:8px;min-width:0}.overseas-authorization input,.overseas-authorization select{min-width:0;width:100%}</style>
